<dialog class="mw-photo-dialog" data-initial-photo-viewer aria-labelledby="initialPhotoViewerTitle">
    <header><h2 id="initialPhotoViewerTitle" data-photo-viewer-name></h2><button type="button" class="mw-button mw-icon" data-photo-viewer-close aria-label="Cerrar fotografía" title="Cerrar fotografía"><span data-maintenance-photo-icon="close" aria-hidden="true"></span></button></header>
    <div class="mw-photo-viewer-image"><img data-photo-viewer-image alt="Fotografía de evidencia"></div>
</dialog>
